#!/usr/bin/env python3
"""Regenerate pqc_suite/kat_fndsa.h from c-fn-dsa's test_fndsa.c.

usage: gen_kat.py path/to/c-fn-dsa/test_fndsa.c > pqc_suite/kat_fndsa.h
"""
import re
import sys

src = open(sys.argv[1]).read()
out = ['''/* Known-answer test data for FN-DSA, copied from c-fn-dsa test_fndsa.c
 * (commit 1b858880, public domain). Generated by suites/fndsa/gen_kat.py.
 *
 * KAT_n_HASH[j] = SHA3-256(sk || vk || sig) for the key pair and signature
 * derived from seed = logn || j (see job_kat() in suite.c).
 * KAT_n_VK / KAT_n_SIG: a verifying key and a signature over the raw message
 * "message" with context "context". */
#ifndef KAT_FNDSA_H
#define KAT_FNDSA_H

#include <stdint.h>
''']
for name in ['KAT_512', 'KAT_1024']:
    m = re.search(r'static const char \*const %s\[\] = \{(.*?)\};' % name, src, re.S)
    hx = re.findall(r'"([0-9a-f]{64})"', m.group(1))
    assert len(hx) == 10, (name, len(hx))
    out.append('static const uint8_t %s_HASH[10][32] = {' % name)
    for h in hx:
        out.append('    {' + ', '.join('0x%02x' % x for x in bytes.fromhex(h)) + '},')
    out.append('};\n')
for name in ['KAT_512_VK', 'KAT_512_SIG', 'KAT_1024_VK', 'KAT_1024_SIG']:
    m = re.search(r'static const uint8_t %s\[\] = \{(.*?)\};' % name, src, re.S)
    vals = re.findall(r'0x[0-9A-Fa-f]{2}', m.group(1))
    out.append('static const uint8_t %s[%d] = {' % (name, len(vals)))
    for i in range(0, len(vals), 12):
        out.append('    ' + ', '.join(vals[i:i + 12]) + ',')
    out.append('};\n')
out.append('#endif /* KAT_FNDSA_H */')
sys.stdout.write('\n'.join(out) + '\n')
